target:
Violate assertion '
    // 1. 复位保护：复位期间不进行检查
    disable iff (!rstn_top) 

    // 2. 触发条件 (前件)：检测到发往 TCDM 的有效授权
    // 这里假设我们只关心是否有任何授权发生，用 != 0 进行严格的逻辑判断
    (top_wrapper.soc_interconnect.TCDM_data_gnt_DEM_TO_XBAR != 0) |-> // 3. 蕴含操作符 (Implication)：只有左边成立时，才检查右边

    // 4. 约束条件 (后件)：地址必须严格在合法区间内
    ((top_wrapper.soc_interconnect.TCDM_data_add_DEM_TO_XBAR >= 32'h1C00_0000) && 
     (top_wrapper.soc_interconnect.TCDM_data_add_DEM_TO_XBAR <= 32'h1C08_0000))' in jg_bind_inst

target_expr:
// 1. 复位保护：复位期间不进行检查
    disable iff (!jg_bind_inst.rstn_top) 

    // 2. 触发条件 (前件)：检测到发往 jg_bind_inst.TCDM 的有效授权
    // 这里假设我们只关心是否有任何授权发生，用 != 0 进行严格的逻辑判断
    (top_wrapper.soc_interconnect.TCDM_data_gnt_DEM_TO_XBAR != 0) |-> // 3. 蕴含操作符 (jg_bind_inst.Implication)：只有左边成立时，才检查右边

    // 4. 约束条件 (后件)：地址必须严格在合法区间内
    ((top_wrapper.soc_interconnect.TCDM_data_add_DEM_TO_XBAR >= 32'h1C00_0000) && 
     (top_wrapper.soc_interconnect.TCDM_data_add_DEM_TO_XBAR > 32'h1C08_0000))
